"""Debates (oitava leva): primitivismo, trabalho, corrupção, religião na política."""
SEP = 'https://plato.stanford.edu/entries/'
WE = 'https://en.wikipedia.org/wiki/'
TF, RS, JE = 'Tecnologia e futuro', 'Riqueza e sociedade', 'Justiça e Estado'

DEBATES8 = [
dict(s='primitivismo', n='Primitivismo: a civilização foi um erro?', t=TF, r='Rousseau, o anarcoprimitivismo e a nostalgia da vida pré-agrícola. O que a crítica acerta sobre a civilização, e o que ela esquece sobre quem viveria sem ela.',
 v='O primitivismo diz que a civilização, a partir da agricultura, trouxe hierarquia, trabalho, doença, guerra e alienação, e que a vida de caçadores-coletores era mais livre, igualitária e saudável. Versões suaves criticam a tecnologia; a radical (John Zerzan) propõe desfazer a civilização. A pergunta ética é dupla: a crítica está certa? E o que a “volta” custaria?',
 lados=[('O que a crítica acerta', ['A agricultura trouxe desigualdade, Estados, escravidão, epidemias e, em média, piora na saúde dos primeiros agricultores; a evidência arqueológica apoia parte da tese.', 'Sociedades de caçadores-coletores tendem a ser mais igualitárias e a trabalhar menos horas; a “pobreza” delas é em parte um julgamento nosso.', 'A tecnologia não é neutra: cria dependências, concentra poder e produziu as armas e as fazendas industriais; a crítica ecológica tem fundamento.', 'A domesticação de animais é um dos pontos de partida da exploração em massa que a ética animal denuncia.']),
        ('O que a volta custaria', ['Oito bilhões de pessoas não vivem de caça e coleta: a transição implicaria a morte da maior parte da humanidade. Nenhuma ética que conte as vidas presentes aceita isso.', 'Mortalidade infantil, dor sem analgesia, infecções e violência eram altas na vida pré-agrícola; a nostalgia esquece quem morria.', 'A civilização produziu também a medicina, a escrita, os direitos e a própria crítica da civilização.', 'O sofrimento dos animais selvagens não é resolvido por humanos voltarem à natureza; ele existia antes e continuaria.', 'A tecnologia que criou as fazendas industriais pode acabar com elas: proteína sem animais, vacinas, alternativas que um mundo primitivo não teria.'])],
 c=['A crítica à civilização e a proposta de desfazê-la são coisas diferentes: pode-se aceitar a primeira e rejeitar a segunda.', 'Há versões moderadas (decrescimento, tecnologia apropriada, crítica ao consumo) que não exigem a catástrofe e merecem debate próprio.', 'O primitivismo radical muitas vezes idealiza a natureza como boa em si, o que é a falácia naturalista e um ecocentrismo que esquece quem sofre na natureza.'],
 p=('parcial', 'A crítica primitivista acerta ao mostrar que a civilização teve custos enormes, inclusive para os animais, e que a tecnologia não é neutra. Mas a proposta de desfazê-la falha por qualquer ética que conte vidas presentes: implicaria a morte de bilhões e o retorno de sofrimentos que a medicina e a abundância reduziram. O que sobrevive é a pergunta sobre que tecnologias e que formas de organização servem a quem sente, e isso é o debate sobre tecnologia e sobre o clima, não sobre voltar.'),
 teorias=[('utilitarismo-classico', 'Utilitarismo', 'A conta das vidas presentes e futuras condena a volta; aceita a crítica ao que a civilização faz de errado.'), ('sencientismo', 'Sencientismo', 'A natureza não é boa em si: animais sofriam antes e sofreriam depois; o critério é o sofrimento, não a “naturalidade”.'), ('ecocentrismo', 'Ecocentrismo', 'A posição mais próxima do primitivismo: o sistema natural como valor; sua tensão com quem sente aparece aqui com força.'), ('etica-das-virtudes', 'Virtudes', 'A crítica ao consumo e à dependência tem raiz nas virtudes da temperança e da autonomia.'), ('existencialismo', 'Existencialismo', 'A alienação é real; a resposta é responsabilidade dentro do mundo que há, não fuga para um que não existe.')],
 licoes=['etica-da-tecnologia', 'etica-climatica', 'sofrimento-dos-animais-selvagens', 'fatos-e-valores'],
 fx=[('Anarcho-primitivism (Wikipédia)', WE + 'Anarcho-primitivism'), ('Discurso sobre a Origem da Desigualdade (Wikipédia)', 'https://pt.wikipedia.org/wiki/Discurso_sobre_a_Origem_e_os_Fundamentos_da_Desigualdade_entre_os_Homens'), ('Sapiens', 'https://www.google.com/search?tbm=bks&q=Harari+Sapiens')]),

dict(s='trabalho', n='Trabalho: dever, dignidade ou necessidade?', t=RS, r='Quem não trabalha não merece comer? O trabalho dignifica? Entre a ética do trabalho, o direito à preguiça e a pergunta sobre o que devemos a quem não pode trabalhar.',
 v='Quase toda sociedade trata o trabalho como dever e como fonte de valor pessoal. Ao mesmo tempo, boa parte do trabalho real é penosa, mal paga ou inútil, e a automação promete reduzi-la. As perguntas: trabalhar é um dever moral? O trabalho dá dignidade, ou a dignidade vem antes? E o que devemos a quem não trabalha?',
 lados=[('A ética do trabalho', ['Reciprocidade: quem recebe da sociedade deve contribuir; viver do trabalho dos outros podendo trabalhar é carona.', 'Realização: o trabalho pode ser fonte de sentido, competência e pertencimento; Aristóteles e Marx, de formas diferentes, viram nele parte do florescimento.', 'Autonomia: sustentar-se é condição de não depender da vontade alheia.', 'Dignidade do trabalho: tradições religiosas e seculares o veem como vocação.']),
        ('A crítica', ['Dignidade não vem do trabalho: vem antes, e por isso quem não pode trabalhar (crianças, doentes, idosos, pessoas com deficiência) não vale menos. Confundir as duas é a origem do desprezo pelos que não produzem.', 'Muito trabalho é penoso e alienante; Lafargue defendeu o “direito à preguiça”, e Graeber documentou empregos que os próprios ocupantes consideram inúteis.', 'O dever de trabalhar é usado para justificar salários indignos e para negar renda a quem precisa; a reciprocidade também obriga quem emprega.', 'A automação torna possível menos trabalho para todos; insistir no dever de trabalhar, quando ele não é mais necessário, é apego a uma norma que perdeu a razão.'])],
 c=['Trabalho remunerado e trabalho de cuidado (criar filhos, cuidar de idosos) são contados de forma diferente, e o segundo é feito sobretudo por mulheres, sem salário.', 'Renda básica universal é o teste do debate: se o dever de contribuir é real, a renda deve ter contrapartida? A evidência de experimentos mostra que poucos deixam de trabalhar.', 'Trabalho e exploração: a questão marxista sobre quem fica com o valor produzido é diferente da questão sobre o dever de trabalhar.'],
 p=('parcial', 'O peso está com uma posição em duas partes: há um dever de contribuir para quem pode, por reciprocidade, mas a dignidade não depende do trabalho, e a sociedade deve a todos, trabalhem ou não, as condições de uma vida digna. A crítica acerta ao mostrar que a ética do trabalho foi usada para desprezar os que não produzem e para aceitar trabalho indigno. A forma da contribuição, e quanto trabalho um mundo automatizado ainda exige, é a pergunta em aberto.'),
 teorias=[('contratualismo-escanloniano', 'Scanlon', 'Que princípio sobre contribuição ninguém rejeitaria? Contribuir quando pode, e receber quando não pode.'), ('utilitarismo-classico', 'Utilitarismo', 'Trabalho vale pelo que produz e pelo que custa a quem o faz; menos trabalho penoso é ganho.'), ('deontologia-kantiana', 'Kant', 'A dignidade é da pessoa, não do que ela produz; o trabalhador não é meio.'), ('etica-das-virtudes', 'Virtudes', 'O trabalho pode ser excelência e pode ser servidão; a diferença está no que ele faz da pessoa.'), ('etica-do-cuidado', 'Cuidado', 'O trabalho que sustenta a vida (cuidar) é o mais invisível e o mais necessário.')],
 licoes=['economia-politica-e-etica', 'igualdade-humana', 'quanto-a-moral-pode-exigir', 'deficiencia-e-etica'],
 fx=[('Work and Labor (Stanford Encyclopedia)', SEP + 'work-labor/'), ('O Direito à Preguiça (Wikipédia)', 'https://pt.wikipedia.org/wiki/O_Direito_%C3%A0_Pregui%C3%A7a'), ('Bullshit Jobs', 'https://www.google.com/search?tbm=bks&q=Graeber+Bullshit+Jobs')]),

dict(s='corrupcao', n='Corrupção: do “jeitinho” ao desvio', t=JE, r='Pagar para não levar multa, furar a fila com um contato, desviar o orçamento: a mesma estrutura em escalas diferentes. Por que é errado, e por que “todo mundo faz” não ajuda.',
 v='Corrupção é usar uma posição de confiança para ganho próprio ou de aliados, contra a regra que a posição deveria servir. Vai do pequeno suborno ao desvio de bilhões. O debate ético não é se é errada (quase ninguém defende), e sim por que, o que a torna tão persistente e se há graus que a tornam aceitável.',
 lados=[('Por que é errada', ['Quebra de confiança: o cargo foi dado para servir a todos; usá-lo para si trai quem o confiou, e torna todo cargo suspeito.', 'Dano difuso e real: dinheiro desviado é hospital sem remédio e escola sem teto; o custo recai sobre quem mais precisa do Estado.', 'Injustiça: quem paga propina passa na frente de quem cumpre a regra; o sistema passa a premiar o desonesto.', 'Universalização: “pago para resolver” só funciona enquanto os outros não pagam; generalizado, destrói o que torna a propina útil.']),
        ('O que se diz em defesa, e por que não se sustenta', ['“É cultural, todo mundo faz”: descreve a prevalência, que é o problema; e sociedades com a mesma cultura mudaram quando as instituições mudaram.', '“Pequena, não faz mal”: a soma das pequenas sustenta a grande, e o hábito forma a pessoa que aceita a grande. A estrutura é a mesma das pequenas trapaças.', '“O sistema é injusto, então é legítimo burlá-lo”: às vezes a regra é injusta, mas a corrupção não a corrige; favorece quem pode pagar, que raramente é a vítima da injustiça.', '“Rouba mas faz”: o dano da corrupção não é só o dinheiro; é a captura do Estado por quem paga, e o que ele “faz” é decidido por eles.'])],
 c=['Corrupção é um problema de ação coletiva: onde todos esperam que os outros sejam corruptos, ser honesto custa caro; a saída é institucional (transparência, punição certa, salários dignos), não só moral.', 'O “jeitinho” mistura criatividade diante de regras absurdas (que pode ser legítima) com burla de regras justas (que não é); o teste é se alguém é prejudicado e se o motivo pode ser dito em público.', 'A indignação seletiva (só com a corrupção do outro lado) é tribalismo e sustenta a corrupção de todos os lados.'],
 p=('forte', 'Há consenso ético: a corrupção é errada por quebrar confiança, causar dano difuso a quem mais precisa e minar a justiça, e as defesas usuais são racionalizações que não passam no teste da universalização. O que o debate acrescenta é que a solução é mais institucional do que moral, que a indignação seletiva é parte do problema, e que a distinção entre burlar regras injustas e regras justas exige honestidade sobre o motivo.'),
 teorias=[('deontologia-kantiana', 'Kant', 'Usar um cargo de confiança para si trata todos os que confiaram como meios; a máxima não é universalizável.'), ('utilitarismo-classico', 'Utilitarismo', 'Dano difuso enorme, concentrado nos mais pobres; nenhum benefício compensa.'), ('consequencialismo-de-regras', 'Consequencialismo de regras', 'A regra “cumpra o cargo” produz Estados que funcionam; as exceções o destroem.'), ('etica-das-virtudes', 'Virtudes', 'Integridade é o que se faz quando ninguém vê; a corrupção é o vício correspondente.'), ('contratualismo-rawlsiano', 'Contratualismo', 'Sob o véu, ninguém aceitaria um Estado capturado por quem paga.')],
 licoes=['imparcialidade', 'tribalismo-moral', 'da-etica-a-politica', 'fraqueza-de-vontade'],
 fx=[('Corruption (Stanford Encyclopedia)', SEP + 'corruption/'), ('Corrupção (Política Para Iniciantes)', 'https://politicaparainiciantes.biblioverse.org/corrupcao.html'), ('Transparência Internacional', 'https://www.transparency.org/')]),

dict(s='religiao-na-politica', n='Religião na política', t=JE, r='Crentes podem votar e legislar segundo sua fé? Argumentos religiosos valem no debate público? O Estado laico, a razão pública e os limites dos dois lados.',
 v='Em sociedades plurais, pessoas de muitas religiões e sem religião decidem juntas. A pergunta não é se religiosos podem participar (podem, como qualquer cidadão), e sim que tipo de razão pode fundar uma lei que vale para todos, e o que a laicidade do Estado exige e não exige.',
 lados=[('Razão pública e laicidade', ['Rawls: leis que coagem a todos devem ser justificáveis com razões que todos possam aceitar em princípio, e não só quem partilha uma fé. “Deus proíbe” não é razão para quem não crê; “isso causa dano a alguém” é.', 'Laicidade protege a própria religião: um Estado que adota uma fé persegue as outras, e a história o mostra. A separação é condição da liberdade religiosa.', 'Leis fundadas só em doutrina religiosa impõem a crentes de outras fés e a não crentes um padrão que eles não têm razão para aceitar.', 'Religiosos podem e devem participar; o que se pede é que traduzam suas razões em termos acessíveis a todos quando se trata de coagir.']),
        ('As objeções à razão pública', ['Exigir tradução é injusto com crentes: eles não podem separar sua moral de sua fé, e a exigência os cala (Wolterstorff).', 'Muitos avanços morais vieram de motivação religiosa, como a abolição e os direitos civis; excluir a religião do debate empobrece a vida pública.', 'A razão “secular” também tem pressupostos não demonstrados; a neutralidade é parcialmente uma ilusão.', 'Laicidade hostil (banir símbolos, excluir religiosos do debate) é uma forma de intolerância.'])],
 c=['Distinguir três coisas: motivação (livre), argumento público (deve ser acessível a todos quando se trata de coagir) e Estado (não pode adotar uma fé).', 'O Brasil é laico pela Constituição e tem forte presença religiosa na política; o teste prático é se uma lei se sustenta sem a premissa religiosa.', 'A objeção de Wolterstorff tem resposta: ninguém pede que o crente abandone a fé, só que, ao coagir os outros, dê razões que os outros possam avaliar; o abolicionismo cristão fez isso.'],
 p=('parcial', 'O peso está com a razão pública e a laicidade: leis que valem para todos precisam de razões que todos possam avaliar, e o Estado não pode adotar uma fé, o que protege a própria liberdade religiosa. As objeções acertam em que a motivação religiosa é legítima e historicamente valiosa, e em que a laicidade não pode virar hostilidade. A síntese: participação plena, tradução das razões quando se coage, e Estado sem religião oficial.'),
 teorias=[('contratualismo-rawlsiano', 'Rawls', 'A razão pública: justificar a coação com razões que todos possam aceitar.'), ('etica-do-discurso', 'Habermas', 'Religiosos participam; o discurso público exige traduzir razões religiosas em razões acessíveis, e seculares devem ajudar na tradução.'), ('utilitarismo-classico', 'Utilitarismo (Mill)', 'Leis se justificam pelo dano evitado, não pela doutrina; a liberdade religiosa produz mais bem do que a imposição.'), ('teoria-do-mandamento-divino', 'Mandamento divino', 'Para quem a adota, a lei divina é a moral; o problema é fundar a coação sobre quem não a adota.'), ('lei-natural', 'Lei natural', 'Tenta dar razões acessíveis à razão para conclusões de origem religiosa; é o modelo de tradução, com seus riscos.')],
 licoes=['etica-e-religiao', 'eticas-religiosas', 'da-etica-a-politica', 'como-discutir-etica'],
 fx=[('Religion and Political Theory (Stanford Encyclopedia)', SEP + 'religion-politics/'), ('Public Reason (Stanford Encyclopedia)', SEP + 'public-reason/'), ('Religião e Estado (Política Para Iniciantes)', 'https://politicaparainiciantes.biblioverse.org/religiao-e-estado.html')]),
]
assert len({d['s'] for d in DEBATES8}) == len(DEBATES8)
